   194  v_buff_size Utils::escapeUtf8Char(const char* sequence, p_char8 buffer){
   195    v_buff_size length;
   196    v_int32 code = oatpp::encoding::Unicode::encodeUtf8Char(sequence, length);
   197    if(code < 0x00010000) {
   198      buffer[0] = '\\';
   199      buffer[1] = 'u';
   200      oatpp::encoding::Hex::writeUInt16(v_uint16(code), &buffer[2]);
   201      return 6;
   202    } else if(code < 0x00200000) {
   203      v_int16 high;
   204      v_int16 low;
   205      oatpp::encoding::Unicode::codeToUtf16SurrogatePair(code, high, low);
   206      buffer[0] = '\\';
   207      buffer[1] = 'u';
   208      oatpp::encoding::Hex::writeUInt16(static_cast<v_uint16>(high), &buffer[2]);
   209      buffer[6] = '\\';
   210      buffer[7] = 'u';
   211      oatpp::encoding::Hex::writeUInt16(static_cast<v_uint16>(low), &buffer[8]);
   212      return 12;
   213    } else {
   214      buffer[0] = '\\';
   215      buffer[1] = 'u';
   216      buffer[2] = '+';
   217      oatpp::encoding::Hex::writeUInt32(static_cast<v_uint32>(code), &buffer[2]);
   218      return 11;
   219    }
   220  }
