   222  oatpp::String Utils::escapeString(const char* data, v_buff_size size, v_uint32 flags) {
   223    v_buff_size safeSize;
   224    v_buff_size escapedSize = calcEscapedStringSize(data, size, safeSize, flags);
   225    if(escapedSize == size) {
   226      return String(data, size);
   227    }
   228    String result(escapedSize);
   229    auto resultData = reinterpret_cast<p_char8>(result->data());
   230    v_buff_size pos = 0;
   231
   232    {
   233      v_buff_size i = 0;
   234      while (i < safeSize) {
   235        v_char8 a = static_cast<v_char8>(data[i]);
   236        if (a < 32) {
   237
   238          switch (a) {
   239
   240            case '\b': resultData[pos] = '\\'; resultData[pos + 1] = 'b'; pos += 2; break;
   241            case '\f': resultData[pos] = '\\'; resultData[pos + 1] = 'f'; pos += 2; break;
   242            case '\n': resultData[pos] = '\\'; resultData[pos + 1] = 'n'; pos += 2; break;
   243            case '\r': resultData[pos] = '\\'; resultData[pos + 1] = 'r'; pos += 2; break;
   244            case '\t': resultData[pos] = '\\'; resultData[pos + 1] = 't'; pos += 2; break;
   245
   246            default:
   247              resultData[pos] = '\\';
   248              resultData[pos + 1] = 'u';
   249              oatpp::encoding::Hex::writeUInt16(a, &resultData[pos + 2]);
   250              pos += 6;
   251              break;
   252
   253          }
   254
   255          i++;
   256
   257        }
   258        else if (a < 128) {
   259
   260          switch (a) {
   261            case '\"': resultData[pos] = '\\'; resultData[pos + 1] = '"'; pos += 2; break;
   262            case '\\': resultData[pos] = '\\'; resultData[pos + 1] = '\\'; pos += 2; break;
   263
   264            case '/':
   265              if((flags & FLAG_ESCAPE_SOLIDUS) > 0) {
   266                resultData[pos] = '\\';
   267                resultData[pos + 1] = '/';
   268                pos += 2;
   269              } else {
   270                resultData[pos] = static_cast<v_char8>(data[i]);
   271                pos++;
   272              }
   273              break;
   274
   275            default:
   276              resultData[pos] = static_cast<v_char8>(data[i]);
   277              pos++;
   278              break;
   279
   280          }
   281
   282          i++;
   283        }
   284        else {
   285          v_buff_size charSize = oatpp::encoding::Unicode::getUtf8CharSequenceLength(a);
   286          if (charSize != 0) {
   287            if (!(flags & FLAG_ESCAPE_UTF8CHAR)) {
   288              std::memcpy(reinterpret_cast<void*>(&resultData[pos]), reinterpret_cast<void*>(const_cast<char*>(&data[i])), static_cast<size_t>(charSize));
   289              pos += charSize;
   290            }
   291            else {
   292              pos += escapeUtf8Char(&data[i], &resultData[pos]);
   293            }
   294            i += charSize;
   295          }
   296          else {
   297            // invalid char
   298            resultData[pos] = static_cast<v_char8>(data[i]);
   299            i++;
   300            pos++;
   301          }
   302        }
   303      }
   304    }
   305
   306    if(size > safeSize){
   307      for(v_buff_size i = pos; static_cast<size_t>(i) < result->size(); i ++){
   308        resultData[i] = '?';
   309      }
   310    }
   311
   312    return result;
   313  }
